import json
from data import *
def head(title, desc, url, image, fonts, extra=''):
    return f'''<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>{E(title)}</title><meta name="description" content="{E(desc)}"><meta name="robots" content="noindex,follow"><link rel="canonical" href="{url}">
<meta property="og:type" content="website"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:image" content="{image}"><meta property="og:url" content="{url}"><meta name="twitter:card" content="summary_large_image">
<link rel="icon" href="../img/sp-grifes-icone.png">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?{fonts}&display=swap" rel="stylesheet"><script>document.addEventListener('error',function(e){{var t=e.target;if(t.tagName==='IMG'&&t.src.indexOf('i0.wp.com/')>-1&&!t.dataset.fb){{t.dataset.fb=1;t.src='https://'+t.src.split('i0.wp.com/')[1].split('?')[0]}}}},true);</script>{extra}'''
VID_JS = '''<script>document.addEventListener('error',function(e){var t=e.target;if(t.tagName==='IMG'&&t.src.indexOf('i0.wp.com/')>-1&&!t.dataset.fb){t.dataset.fb=1;t.src='https://'+t.src.split('i0.wp.com/')[1].split('?')[0]}},true);</script><script>(function(){function go(el){if(el.querySelector('iframe'))return;var f=document.createElement('iframe');f.src='https://www.youtube.com/embed/'+el.dataset.v+'?rel=0&modestbranding=1&playsinline=1&autoplay=1';f.title=el.dataset.t||'Vídeo SP Grifes';f.setAttribute('allow','autoplay; encrypted-media; picture-in-picture; web-share');f.setAttribute('allowfullscreen','');el.textContent='';el.appendChild(f)}document.querySelectorAll('[data-v]').forEach(function(el){el.addEventListener('click',function(){go(el)})})})();</script>'''
def vcard(vid, title, cls='vv'):
    return f'''<div class="{cls}" data-v="{vid}" data-t="{E(title)}" role="button" tabindex="0" aria-label="Assistir: {E(title)}"><img src="https://i.ytimg.com/vi/{vid}/oardefault.jpg" onerror="this.onerror=null;this.src='https://i.ytimg.com/vi/{vid}/hqdefault.jpg'" alt="{E(title)}" loading="lazy" width="360" height="640"><span class="vp" aria-hidden="true"></span><em>Toque para assistir</em></div>'''
VCSS = '.vv{position:relative;aspect-ratio:9/16;border-radius:18px;overflow:hidden;background:#000;cursor:pointer}.vv img{width:100%;height:100%;object-fit:cover;display:block;filter:brightness(.88)}.vv iframe{width:100%;height:100%;border:0;display:block}.vv .vp{position:absolute;left:50%;top:50%;width:64px;height:64px;margin:-32px 0 0 -32px;border-radius:50%;background:#ff0033;box-shadow:0 10px 30px rgba(0,0,0,.45)}.vv .vp:after{content:"";position:absolute;left:25px;top:19px;border-style:solid;border-width:13px 0 13px 21px;border-color:transparent transparent transparent #fff}.vv em{position:absolute;left:0;right:0;bottom:14px;text-align:center;font-style:normal;font-weight:800;color:#fff;text-shadow:0 2px 10px rgba(0,0,0,.8);font-size:14px}'
def faq_ld(pairs):
    return '<script type="application/ld+json">' + json.dumps({"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in pairs]}, ensure_ascii=False) + '</script>'
def store_ld(url, name):
    return '<script type="application/ld+json">' + json.dumps({"@context":"https://schema.org","@type":"ClothingStore","name":"SP Grifes","alternateName":name,"url":url,"image":"https://blog.spgrifes.com.br/wp-content/uploads/2026/11/camiseta-gucci-preta-faixa-vermelha-sp-grifes-capa.jpg","address":{"@type":"PostalAddress","streetAddress":"Rua Monsenhor Andrade, 987 – Shopping Feira da Madrugada, Piso 1, Corredor D, Loja 1202","addressLocality":"São Paulo","addressRegion":"SP","postalCode":"03009-100","addressCountry":"BR"},"openingHours":"Mo-Sa 07:00-16:00","sameAs":[LOJA,BLOG,IG,YT]}, ensure_ascii=False) + '</script>'
def wa_share(text):
    from urllib.parse import quote
    return 'https://wa.me/?text=' + quote(text)
